/// Unanswered inbound inter-agent mail — the records every
/// context-bounding tier must keep until a reply exists (PR #2435
/// addendum).
///
/// Delivered mail is user-ROLE data: the DM shape (`from <id>: …`), the
/// channel shape (`from <id> in #<channel>: …`) or any text carrying the
/// channel reply anchor ([isAgentMailText] is the ONE text predicate).
/// Two belts existed before this module, and neither was mechanical:
///
/// - the prompt-level `## Open User Requests` section (issue #81 v2)
///   instructs the judge to carry open asks into the summary — but the
///   judge decides openness ("the summarizer LLM judges openness",
///   issue #81 AC9), and a judge that under-summarizes loses the ask;
/// - the ledger's exempt tag folds DM-shaped mail out of hide picks via
///   [isSyntheticUserText] — but channel-delivered mail (the DAP shape
///   every multi-agent session carries) matches neither the exempt tag
///   nor any other protection, so the relief's keep-N hide, the judge's
///   picks and the local trim valve all folded it like noise.
///
/// The live clip that pinned the invariant: a peer's mail delivered
/// into a busy agent's session, the autonomous chain paused on its
/// budget with one message queued — while any of those tiers could have
/// folded earlier delivered-but-unanswered mail away.
///
/// The invariant here: an inbound mail record with NO later assistant
/// record is an OPEN request — never a judge hide pick, never a relief
/// hide candidate, never dropped by the local trim valve. Once a later
/// assistant record exists the mail folds like any other data.
///
/// Mirrors [newestUserTurnRecordIds] consumers: the structured engine's
/// foldable filter and `validateHidePicks` pins, the emergency relief's
/// keep-N veto, and `localTrimValve`'s carried region. Pure functions
/// over records and messages; no policy lives here. The reply test is
/// deliberately conservative — ANY later assistant record counts as a
/// reply (a precise per-channel match would parse delivery envelopes;
/// the conservative view only over-protects by a turn, never loses).
library;

import '../context.dart' show UserMessage;
import '../session/session_record.dart';
import '../types.dart' show AssistantMessage, Message, ToolCall;
import '../user_text.dart' show isAgentMailText, userMessageText;

/// Whether a session [record] is delivered inbound inter-agent mail: a
/// user-role message whose text carries a mail delivery shape.
bool isInboundAgentMailRecord(SessionRecord record) {
  if (record is! MessageRecord) return false;
  final message = record.message;
  return message is UserMessage &&
      isAgentMailText(userMessageText(message.content));
}

/// Conservative reply evidence: a later assistant record that speaks
/// BACK — carries an `agent_message` tool call (how inter-agent replies
/// travel) or is pure prose with no tool calls at all. An assistant
/// carrier with ordinary tool calls (`read`, `bash`, …) is the agent
/// WORKING after the mail, not answering it — in an agentic session
/// such records follow every delivery, and counting them as replies
/// would make the invariant dead code (the exact first draft's bug: a
/// read carrier closed every mail, so the relief folded it anyway).
bool _isReplyRecord(SessionRecord record) {
  if (record is! MessageRecord) return false;
  final message = record.message;
  if (message is! AssistantMessage) return false;
  final calls = message.content.whereType<ToolCall>().toList();
  return calls.isEmpty || calls.any((call) => call.name == 'agent_message');
}

/// The record ids of unanswered inbound inter-agent mail on a session
/// [path]: every mail record with NO later assistant record. Callers
/// treat the ids like pins — the records never fold into a checkpoint,
/// never enter a judge hide pick and never join a relief hide
/// candidate; the trim valve carries them across its cut.
Set<String> unansweredInboundMailRecordIds(List<SessionRecord> path) {
  final open = <String>{};
  var seenReply = false;
  for (var i = path.length - 1; i >= 0; i--) {
    final record = path[i];
    if (seenReply) continue;
    if (_isReplyRecord(record)) {
      seenReply = true;
    } else if (isInboundAgentMailRecord(record)) {
      open.add(record.id);
    }
  }
  return open;
}

bool _hasReplyCall(AssistantMessage message) => message.content
    .whereType<ToolCall>()
    .any((call) => call.name == 'agent_message');

/// The message-level view of the same invariant for `localTrimValve`
/// (which sees live [Message]s, not records): the indices of unanswered
/// inbound mail, ascending.
List<int> unansweredAgentMailMessageIndices(List<Message> messages) {
  final indices = <int>[];
  var seenReply = false;
  for (var i = messages.length - 1; i >= 0; i--) {
    final message = messages[i];
    if (seenReply) continue;
    if (message is AssistantMessage &&
        (_hasReplyCall(message) ||
            message.content.whereType<ToolCall>().isEmpty)) {
      seenReply = true;
    } else if (message is UserMessage &&
        isAgentMailText(userMessageText(message.content))) {
      indices.add(i);
    }
  }
  return indices.reversed.toList();
}

/// The newest REAL user turn — the one record every context-bounding
/// tier must keep (gh-2411).
///
/// The fixed request overhead (system prompt + tool schemas) plus one
/// large tool result can push a transcript over a small window while the
/// user's question is still the newest turn. Every tier that bounds the
/// live context used to protect only the protected tail and
/// `messages.last`: the emergency trim valve kept the tool RESULT and
/// dropped the question two records back, the quality checkpoint folded
/// the range including it, and the record tag (`m19`) was the only trace
/// the model saw of what the user asked.
///
/// This module is the ONE definition of "the newest real user turn"
/// shared by those tiers: a user-role message whose text is NOT
/// synthetic harness content ([isSyntheticUserText] — the same predicate
/// the context ledger's `·exempt` tag and `validateHidePicks` use), so a
/// system notice, a steering injection or an agent-mail line is never
/// mistaken for the user's own words. Pure functions over messages and
/// session records; no policy lives here.
library;

import '../context.dart';
import '../session/session_record.dart';
import '../types.dart';
import '../user_text.dart'
    show
        isCheckpointSummaryText,
        isSyntheticUserText,
        opensWithProjectionMarker,
        userMessageText;

/// Whether [message] is the user's own turn: a user-role message whose
/// flattened text is not synthetic harness content.
bool isRealUserTurn(Message message) =>
    message is UserMessage &&
    !isSyntheticUserText(userMessageText(message.content));

/// The index of the newest real user turn in [messages], or `-1` when
/// the list carries none (a tool-result-only tail, a transcript of
/// notices).
int newestRealUserTurnIndex(List<Message> messages) {
  for (var i = messages.length - 1; i >= 0; i--) {
    if (isRealUserTurn(messages[i])) return i;
  }
  return -1;
}

/// The record ids the invariant protects on a session [path]: the newest
/// real user turn's record (its ledger pair group is the record itself —
/// only an assistant carrier and its results group). Empty when the path
/// carries no real user turn. Callers treat the ids like pins: the
/// record never folds into a checkpoint, never hides and bounds the trim
/// valve's kept region from below.
int newestRealUserTurnRecordIndex(List<SessionRecord> path) {
  for (var i = path.length - 1; i >= 0; i--) {
    final record = path[i];
    if (record is MessageRecord && isRealUserTurn(record.message)) return i;
  }
  return -1;
}

Set<String> newestUserTurnRecordIds(List<SessionRecord> path) {
  final index = newestRealUserTurnRecordIndex(path);
  return index < 0 ? const {} : {path[index].id};
}

/// gh-241 follow-up #5e (E4/E6): whether [message] is a rendered
/// boundary summary — the user-ROLE text a checkpoint projects as.
bool isBoundarySummary(Message message) =>
    message is UserMessage &&
    isCheckpointSummaryText(userMessageText(message.content));

/// gh-241 follow-up #5e (E1/E6): the leading run of projection markers
/// at the head of [messages] — hidden-range markers, checkpoint
/// summaries and fold pointers, oldest first. A resume walk that stops
/// at the newest durable boundary opens the context with exactly that
/// run (the boundary cluster's rendering); an empty run means the
/// context opens on conversation.
List<Message> leadingBoundaryCluster(List<Message> messages) {
  var end = 0;
  while (end < messages.length) {
    final message = messages[end];
    if (message is! UserMessage) break;
    if (!opensWithProjectionMarker(userMessageText(message.content))) break;
    end++;
  }
  return messages.sublist(0, end);
}

/// The boundary summaries the context-bounding tiers pin like the
/// newest real user turn (gh-241 follow-up #5e, E4): every checkpoint
/// summary of the leading boundary cluster plus the newest checkpoint
/// summary anywhere in [messages] — after a compaction pass the newest
/// summary rides its own tail record. Indices ascend; older summaries
/// beyond these stay droppable.
List<int> pinnedBoundarySummaryIndices(List<Message> messages) {
  final cluster = leadingBoundaryCluster(messages).length;
  var newest = -1;
  for (var i = 0; i < messages.length; i++) {
    if (isBoundarySummary(messages[i])) newest = i;
  }
  return [
    for (var i = 0; i < messages.length; i++)
      if (isBoundarySummary(messages[i]) && (i < cluster || i == newest)) i,
  ];
}

/// gh-241 follow-up #5e (E1/E6): the NEWEST durable boundary's checkpoint
/// summaries — the run of consecutive projection markers that ends at
/// the newest checkpoint summary in [messages], reduced to the summaries
/// themselves, oldest first. A window that opens at its boundary holds
/// the run at the head; a checkpoint appended after the tail it
/// summarizes (tail layout) holds it at the end — the caller decides
/// where the request opens. Empty when the projection carries no
/// checkpoint summary.
List<Message> newestBoundarySummaries(List<Message> messages) {
  var last = -1;
  for (var i = 0; i < messages.length; i++) {
    if (isBoundarySummary(messages[i])) last = i;
  }
  if (last < 0) return const [];
  var first = last;
  while (first > 0 && _isProjectionMarker(messages[first - 1])) {
    first--;
  }
  return [
    for (var i = first; i <= last; i++)
      if (isBoundarySummary(messages[i])) messages[i],
  ];
}

bool _isProjectionMarker(Message message) =>
    message is UserMessage &&
    opensWithProjectionMarker(userMessageText(message.content));

/// Per-session calibration of the fixed request-overhead estimate
/// (gh-2411).
///
/// [OverheadCalibration] is a pure value: the multiplier the provider's
/// own usage report earned for the unanchored request estimate. The
/// heuristic density (`overheadCharsPerToken`) is honest on average and
/// wrong per provider — tokenizers differ, and a system prompt full of
/// paths, ids or non-English prose is denser than English. The first
/// valid usage of a session settles the question (`fromUsage`); the
/// host carries the value forward, so the ctx meter, the over-window
/// guard and the compaction trigger stay honest on UNANCHORED estimates
/// too: a fresh or resumed session, and every turn after a compaction
/// zeroed the usage anchors. No policy lives here — the derivation from
/// a transcript is `deriveOverheadCalibration` in `token_estimation.dart`.
library;

/// The measured multiplier over the unanchored request estimate.
final class OverheadCalibration {
  /// Creates a calibration with [ratio].
  const OverheadCalibration(this.ratio, {this.measured = false});

  /// No calibration: the heuristic stands as is.
  static const uncalibrated = OverheadCalibration(1.0);

  /// A provider reporting FEWER tokens than the heuristic may LOWER the
  /// meter — down to this floor. An under-read estimate silently overruns
  /// the window (the gh-2411 incident), but an over-read one is not free
  /// either: the owner's live test (glm-5.3-flash, 34 tools) charged
  /// 15,792 tokens where the heuristic read 24,348 (ratio 0.65), and
  /// clamped at 1.0 that over-read held the soft-window regime on every
  /// prompt — no pass ever ran and the context grew to 114%. Only the
  /// FIRST, overhead-dominated anchor moves the meter
  /// (`deriveOverheadCalibration`); the floor keeps a degenerate report
  /// from erasing the overhead.
  static const double minRatio = 0.6;

  /// A degenerate usage report (a units mismatch, a summed field) must
  /// not multiply the window away.
  static const double maxRatio = 4.0;

  /// The multiplier over the unanchored request estimate.
  final double ratio;

  /// Whether a provider usage report produced this value. A session
  /// consumes its FIRST valid usage and keeps the result — later anchors
  /// (a transcript far larger than the overhead, diluting the ratio
  /// toward 1.0) never overwrite it, and a measurement that clamped to
  /// [minRatio] still counts as taken.
  final bool measured;

  /// Whether the provider's usage moved the heuristic at all.
  bool get isCalibrated => ratio != 1.0;

  /// The calibration from ONE request: [promptTokens] is what the
  /// provider charged for the request (input + cache reads/writes, i.e.
  /// its total minus the output), [unanchoredRequestTokens] our
  /// heuristic estimate of the same request. Clamped to
  /// [minRatio]..[maxRatio]; a zero or degenerate input yields
  /// [uncalibrated].
  factory OverheadCalibration.fromUsage({
    required int promptTokens,
    required int unanchoredRequestTokens,
  }) {
    if (promptTokens <= 0 || unanchoredRequestTokens <= 0) {
      return uncalibrated;
    }
    return OverheadCalibration(
      (promptTokens / unanchoredRequestTokens).clamp(minRatio, maxRatio),
      measured: true,
    );
  }

  /// The calibrated token count of an [unanchoredTokens] estimate (the
  /// estimate itself when uncalibrated; never negative).
  int apply(int unanchoredTokens) => unanchoredTokens <= 0
      ? unanchoredTokens
      : (unanchoredTokens * ratio).ceil();
}

/// Raise the process's open-file soft limit at startup (gh-2415).
///
/// The macOS launchd default soft limit is 256 descriptors; a long-lived
/// orchestrator (directory watchers, keep-alive sockets, one pipe pair per
/// bash call, adopted jobs) sits near it at rest and hits `EMFILE` on
/// every spike — the bash tool died with `ProcessException: Too many open
/// files` and the receipt writer lost writes. The hard limit is normally
/// unlimited, so the soft limit is the only thing in the way.
///
/// Pure decision core: [FdLimitRaiser] plans and applies the raise over an
/// injected [FdLimitBackend] exactly once per process; the VM backend
/// (`getrlimit`/`setrlimit` through dart:ffi) lives in `fd_limit_io.dart`
/// and web/Windows hosts get the stub — `lib/` stays pure Dart.
library;

/// The soft limit the raise targets — the `ulimit -n 10240` the team runs
/// with; enough for concurrent subagents each spawning hook processes.
const int fdLimitTarget = 10240;

/// One `getrlimit(RLIMIT_NOFILE)` reading. [hard] below 0 = unlimited
/// (`RLIM_INFINITY`, which the 64-bit `rlim_t` reports as all-ones).
typedef FdLimits = ({int soft, int hard});

/// The platform seam: reads the current limits and sets a new soft limit.
/// Implementations never throw — a failure answers false / null — so the
/// raise is strictly best-effort.
abstract interface class FdLimitBackend {
  /// The current limits, or null when the platform cannot report them.
  FdLimits? getLimits();

  /// Sets the soft limit to [soft] (the hard limit is never lowered).
  /// Whether `setrlimit` accepted it.
  bool setSoftLimit(int soft);
}

/// What one [FdLimitRaiser.apply] did.
enum FdLimitOutcome {
  /// `setrlimit` raised the soft limit.
  raised,

  /// Nothing to do: the soft limit already meets the target.
  alreadySufficient,

  /// The platform has no `getrlimit` (web, Windows) or the hard limit
  /// leaves nothing to raise (hard ≤ soft).
  unsupported,

  /// `setrlimit` refused (a sandboxed or hardened host).
  refused,
}

/// One-shot soft-limit raise, pure over [backend].
///
/// Exactly ONCE per instance (a process calls [apply] from `main()`; a
/// second call — or any call after a refusal — is a no-op answering
/// null, so a `--version` boot never pays the syscall twice and a
/// sandboxed host is not retried on every command). [target] is capped at
/// the hard limit; a hard limit at or below the current soft limit means
/// nothing can be raised.
final class FdLimitRaiser {
  FdLimitRaiser({required this.backend, this.target = fdLimitTarget});

  /// Null on platforms without `RLIMIT_NOFILE` semantics (web, Windows).
  final FdLimitBackend? backend;

  /// The soft limit to reach, capped at the hard limit.
  final int target;

  var _applied = false;

  /// Whether [apply] already ran (whatever it decided).
  bool get applied => _applied;

  /// The raise plan for [limits]: the soft limit to set, or null when
  /// nothing should change. Pure — the unit tests pin every branch.
  int? planFor(FdLimits limits) {
    if (limits.soft >= target) return null; // already sufficient
    final cap = limits.hard < 0
        ? target
        : (limits.hard < target ? limits.hard : target);
    if (cap <= limits.soft) return null; // hard limit leaves no room
    return cap;
  }

  /// Applies the raise once. Null when this instance already ran or the
  /// platform has no backend.
  FdLimitOutcome? apply() {
    if (_applied) return null;
    _applied = true;
    final b = backend;
    final current = b?.getLimits();
    if (b == null || current == null) return FdLimitOutcome.unsupported;
    final planned = planFor(current);
    if (planned == null) {
      // Two different "nothing to set": already there vs. a hard limit
      // that leaves no room (the host cannot help us).
      return current.soft >= target
          ? FdLimitOutcome.alreadySufficient
          : FdLimitOutcome.unsupported;
    }
    return b.setSoftLimit(planned)
        ? FdLimitOutcome.raised
        : FdLimitOutcome.refused;
  }
}

/// fd-pressure guard contracts for the tool layer (gh-2415).
///
/// A long-lived session at the descriptor soft limit saw the bash tool
/// die with an uncaught `ProcessException: Too many open files` (surfaced
/// to the model as "the tool may be unavailable in this environment") and
/// the receipt writer lose writes on every tick. This file is the pure
/// half: the snapshot shape, the threshold, the errno-24 recognizer shared
/// by the bash tool and the receipt writer, and the typed, visible error
/// the bash tool raises instead of the uncaught exception. The VM probe
/// lives in `fd_pressure_io.dart` (behind a web stub).
library;

import '../exceptions.dart';

/// One fd-table sample: open descriptors vs the process's soft limit.
typedef FdPressureSnapshot = ({int open, int limit});

/// The fraction of the soft limit at which the bash tool path guards.
const double fdPressureThreshold = 0.8;

/// Whether [snapshot] is in the pressure zone (above [fdPressureThreshold]
/// of a positive limit). Pure.
bool fdPressureExceeded(FdPressureSnapshot snapshot) =>
    snapshot.limit > 0 && snapshot.open > snapshot.limit * fdPressureThreshold;

/// The text a sample renders in errors and notices: `N/M open`.
String fdPressureLabel(FdPressureSnapshot snapshot) =>
    '${snapshot.open}/${snapshot.limit} open';

/// Whether [error] is the OS saying the descriptor table is full: errno 24
/// (`EMFILE` on macOS and Linux alike) or its message, read off the
/// rendered text — pure (no `dart:io` types), so a harness-wrapped
/// `FileError`, a `ProcessException` and a `FileSystemException` all
/// match.
bool isFdPressureError(Object error) {
  final text = error.toString();
  return text.contains('Too many open files') ||
      text.contains('errno 24') ||
      text.contains('EMFILE');
}

/// The typed, visible bash tool error for descriptor exhaustion (gh-2415):
/// operational (a [ToolValidationException], so the loop renders it as a
/// tool error, never "an uncaught exception inside the harness tool
/// implementation") and actionable — it names the pressure and the lever.
final class FdPressureException extends ToolValidationException {
  FdPressureException({required this.open, required this.limit})
    : super(
        'bash',
        'fd pressure: $open/$limit open — retried after closing settled '
            'jobs, still above the limit. Wait for running jobs to settle or '
            'stop one (bash_job action: stop), then retry this call.',
      );

  /// The same error for an EMFILE the OS raised before a sample existed
  /// (a spawn failure, a thrown `FileSystemException`): no counts.
  const FdPressureException.unsampled()
    : open = -1,
      limit = -1,
      super(
        'bash',
        'fd pressure: the descriptor table is full (Too many open files) — '
            'wait for running jobs to settle or stop one (bash_job action: '
            'stop), then retry this call.',
      );

  /// Open descriptors at the time of the refusal (-1 when unsampled).
  final int open;

  /// The soft limit in force (-1 when unsampled).
  final int limit;
}

